<script setup lang="ts">
import { onMounted, onUnmounted } from 'vue'

useHead({
  title: 'The Narayan Presence — Conscious Mastery & Life Clarity',
  meta: [
    { name: 'description', content: 'Practical programmes for personal awareness and for building a coaching business, from The Narayan Presence.' }
  ],
  link: [
    { rel: 'preconnect', href: 'https://fonts.googleapis.com' },
    { rel: 'preconnect', href: 'https://fonts.gstatic.com', crossorigin: '' },
    {
      rel: 'stylesheet',
      href: 'https://fonts.googleapis.com/css2?family=Fraunces:ital,opsz,wght@0,9..144,300;0,9..144,400;0,9..144,500;1,9..144,300;1,9..144,400&family=DM+Sans:wght@400;500;700&display=swap'
    },
    { rel: 'stylesheet', href: '/style.css' }
  ]
})

onMounted(() => {
  // Ensure initial active page is displayed based on hash or default to home
  const initialHash = (window.location.hash || '').replace('#', '')
  const initialId = initialHash ? ('pg-' + initialHash) : 'pg-home'
  const activeEl = document.getElementById(initialId) || document.getElementById('pg-home')
  if (activeEl) {
    document.querySelectorAll('.narayan-home-page .page').forEach(p => p.classList.remove('on'))
    activeEl.classList.add('on')
  }

  // Remove any custom cursor circle elements to keep standard clean mouse pointer
  document.querySelectorAll('.cur').forEach(el => el.remove())

  // Interactive parallax tracking for the movable circle structure (orb + mandala)
  const heroEl = document.querySelector('.hero') as HTMLElement | null
  const orbEl = document.querySelector('.hero .orb') as HTMLElement | null

  if (heroEl && orbEl) {
    const handleMouseMove = (e: MouseEvent) => {
      const r = heroEl.getBoundingClientRect()
      const px = ((e.clientX - r.left) / r.width - 0.5) * 2
      const py = ((e.clientY - r.top) / r.height - 0.5) * 2
      heroEl.style.setProperty('--px', px.toFixed(3))
      heroEl.style.setProperty('--py', py.toFixed(3))
      heroEl.style.setProperty('--hx', (e.clientX - r.left) + 'px')
      heroEl.style.setProperty('--hy', (e.clientY - r.top) + 'px')
      
      // Fluid direct spring movement on the orb structure
      orbEl.style.transform = `translate(${(px * 24).toFixed(1)}px, ${(py * 24).toFixed(1)}px)`
    }

    const handleMouseLeave = () => {
      heroEl.style.setProperty('--px', '0')
      heroEl.style.setProperty('--py', '0')
      orbEl.style.transform = 'translate(0px, 0px)'
    }

    heroEl.addEventListener('mousemove', handleMouseMove, { passive: true })
    heroEl.addEventListener('mouseleave', handleMouseLeave)
  }

  // Canvas golden drifting motes particles
  const cv = document.querySelector('canvas.motes') as HTMLCanvasElement | null
  if (cv && heroEl) {
    const ctx = cv.getContext('2d')
    if (ctx) {
      let W = (cv.width = heroEl.clientWidth)
      let H = (cv.height = heroEl.clientHeight)
      const pts: Array<{ x: number; y: number; r: number; vx: number; vy: number; a: number; t: number }> = []
      const numPts = Math.min(80, Math.round((W * H) / 14000))
      for (let i = 0; i < numPts; i++) {
        pts.push({
          x: Math.random() * W,
          y: Math.random() * H,
          r: Math.random() * 1.8 + 0.4,
          vx: (Math.random() - 0.5) * 0.22,
          vy: -Math.random() * 0.28 - 0.05,
          a: Math.random() * 0.6 + 0.25,
          t: Math.random() * 6
        })
      }

      const resize = () => {
        if (!heroEl) return
        W = cv.width = heroEl.clientWidth
        H = cv.height = heroEl.clientHeight
      }
      window.addEventListener('resize', resize)

      let animId: number
      const loop = () => {
        ctx.clearRect(0, 0, W, H)
        for (let i = 0; i < pts.length; i++) {
          const p = pts[i]
          p.x += p.vx
          p.y += p.vy
          p.t += 0.02
          if (p.y < -6) { p.y = H + 6; p.x = Math.random() * W }
          if (p.x < -6) p.x = W + 6
          if (p.x > W + 6) p.x = -6

          const tw = 0.55 + 0.45 * Math.sin(p.t)
          ctx.beginPath()
          ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2)
          ctx.fillStyle = "rgba(236,196,118," + (p.a * tw).toFixed(2) + ")"
          ctx.shadowColor = 'rgba(217,170,85,0.9)'
          ctx.shadowBlur = 8
          ctx.fill()
        }
        animId = requestAnimationFrame(loop)
      }
      loop()
    }
  }

  // Load app.js and fx.js for complete animations & interactivity
  const loadScript = (src: string): Promise<void> => {
    return new Promise((resolve, reject) => {
      const existing = document.querySelector(`script[src="${src}"]`)
      if (existing) {
        existing.remove()
      }
      const s = document.createElement('script')
      s.src = src
      s.defer = true
      s.onload = () => resolve()
      s.onerror = (e) => reject(e)
      document.body.appendChild(s)
    })
  }

  loadScript('/app.js')
    .then(() => loadScript('/fx.js'))
    .catch((err) => console.warn('Script initialization warning:', err))
})
</script>

